"use client";

import { forwardRef } from "react";
import { weaveGridDefaults, type WeaveGridSpecProps } from "../generated/weave-grid.types";
import { cx } from "../utils/cx";
import { motionVars } from "../utils/motion";
import type { PatternDivProps } from "../utils/pattern";

export interface WeaveGridProps extends WeaveGridSpecProps, Omit<PatternDivProps, keyof WeaveGridSpecProps> {}

/**
 * Warp and weft threads crossing, with an ember shuttle that passes through slowly. CSS only.
 * Decoration: hidden from assistive technology, ignores the pointer.
 */
export const WeaveGrid = forwardRef<HTMLDivElement, WeaveGridProps>(function WeaveGrid(
  {
    size = weaveGridDefaults.size,
    warpColor = weaveGridDefaults.warpColor,
    weftColor = weaveGridDefaults.weftColor,
    accent = weaveGridDefaults.accent,
    fade = weaveGridDefaults.fade,
    duration = weaveGridDefaults.duration,
    isStill = weaveGridDefaults.isStill,
    className,
    style,
    ...rest
  },
  ref,
) {
  return (
    <div
      {...rest}
      ref={ref}
      aria-hidden="true"
      data-fade={fade ? "edge" : undefined}
      data-rdm-still={isStill || undefined}
      className={cx("rdm-pattern rdm-weave", className)}
      style={{
        ...style,
        ...motionVars({ "--rdm-wc": warpColor, "--rdm-fc": weftColor, "--rdm-ac": accent, "--rdm-p": `${size}px`, "--rdm-d": `${duration}s` }),
      }}
    >
      <div className="rdm-weave-warp" />
      <div className="rdm-weave-weft" />
      <div className="rdm-weave-shuttle" />
    </div>
  );
});

// Generated by rdloom codegen from specs/weave-grid.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** rdloom's signature backdrop: warp and weft threads crossing in a woven grid, with an ember shuttle that passes through slowly. */
export interface WeaveGridSpecProps {
  /**
   * Distance between threads in pixels.
   * @default 24
   */
  size?: number;
  /**
   * Colour of the vertical warp threads.
   * @default "var(--rd-color-border-default)"
   */
  warpColor?: string;
  /**
   * Colour of the horizontal weft threads.
   * @default "var(--rd-color-border-default)"
   */
  weftColor?: string;
  /**
   * Colour of the shuttle pass. Defaults to the ember token.
   * @default "var(--rd-color-ember-500)"
   */
  accent?: string;
  /**
   * Fades the weave out toward its edges.
   * @default true
   */
  fade?: boolean;
  /**
   * Seconds one shuttle pass takes.
   * @default 9
   */
  duration?: number;
  /**
   * Stops all movement. Moving content should be stoppable.
   * @default false
   */
  isStill?: boolean;
}

export const weaveGridDefaults = {
  size: 24,
  warpColor: "var(--rd-color-border-default)",
  weftColor: "var(--rd-color-border-default)",
  accent: "var(--rd-color-ember-500)",
  fade: true,
  duration: 9,
  isStill: false,
} as const;

export const weaveGridMeta = {
  "name": "WeaveGrid",
  "version": "0.1.0",
  "status": "experimental",
  "role": "presentation"
} as const;
